const runId = `${$now.toMillis()}-${Math.floor(Math.random() * 1e6)}`;
const COUNT = 5;

// A small batch, not the full MAX_BULK_ENTITIES cap (nodes/Enterspeed/actions/entity/shared.ts)
// — keeps this CI step fast while still exercising the real saveBulk/deleteBulk code path.
// Shaped like a real `product` entity (see docs.enterspeed.com/api-reference/ingest/save-entities)
// rather than a minimal test payload, since that's what this bulk path actually ingests in production.
const entities = [];
for (let i = 1; i <= COUNT; i++) {
  const originId = `e2e-bulk-${runId}-${i}`;
  const sku = `ENT-E2E-${runId}-${i}`;
  entities.push({
    type: 'product',
    originId,
    originParentId: null,
    url: `/products/e2e-bulk-test-${runId}-${i}`,
    redirects: [],
    properties: {
      sku,
      productName: `E2E Bulk Test Product ${i}`,
      category: 'Footwear > Outdoor > Hiking',
      brand: 'TrailForm',
      priceExclVat: 899,
      currency: 'DKK',
      stockStatus: 'In Stock',
      stockQuantity: 142,
      colour: 'Slate Grey / Burnt Orange',
      sizeRange: 'EU 38-46',
      material: 'Recycled mesh upper, rubber outsole',
      weightGrams: 340,
    },
  });
}

return [{
  json: {
    entities,
    originIds: entities.map((e) => e.originId),
  },
}];

const { entities } = $('Build Test Entities').first().json;
return entities.map((e) => ({
  json: { originId: e.originId, url: e.url, sku: e.properties.sku },
}));

const { originId, sku } = $('Prepare Exists Check').item.json;
const route = $json.route;

if (!route) {
  throw new Error(`Entity ${originId}: no route returned after Save Bulk — entity was not created (or ingest hadn't finished processing yet)`);
}

if (route.sku !== sku) {
  throw new Error(`Entity ${originId}: expected route.sku "${sku}", got ${JSON.stringify(route.sku)}`);
}

const { entities } = $('Build Test Entities').first().json;
return entities.map((e) => ({
  json: { originId: e.originId, url: e.url, sku: e.properties.sku },
}));

const { originId, sku } = $('Prepare Deleted Check').item.json;
const response = $json;

// nodes/Enterspeed/actions/router.ts reports a continueOnFail'd request as
// { error, description } instead of throwing — that's the expected shape here,
// since the route should 404 once the entity is actually deleted.
const wasReportedMissing = typeof response.error === 'string';
const hasLiveRoute = response.route && response.route.sku === sku;

if (hasLiveRoute) {
  throw new Error(`Entity ${originId}: still present after Delete Bulk (route.sku=${response.route.sku})`);
}

if (!wasReportedMissing && response.route !== null) {
  throw new Error(`Entity ${originId}: unexpected response after Delete Bulk — neither a clear 'not found' error nor a live route: ${JSON.stringify(response)}`);
}
